-- Q11. Find the average order value for completed orders.
select avg(Quantity * Unit_Price) from orders where Order_status = 'Completed';

-- Q12. Find the total revenue generated by each customer segment.

select c.customer_segment, sum(o.Quantity * o.Unit_Price) as Revenue from orders as o
left join customers as c on o.customer_Id = c.Customer_Id group by c.customer_segment;

-- Q13. Find the top 5 products by total revenue from completed orders. Return product name and revenue.

select
	p.Product_Name,
    sum(Unit_Price * Quantity) as revenue 
from orders as o 
	left join products as p on o.Product_ID = p.Product_Id 
where o.Order_status = 'Completed'
	group by p.Product_Name 
order by revenue desc
limit 5;

-- Q14. Find the number of completed orders for each customer state.

SELECT 
    c.state, COUNT(order_Id) AS Completed_Orders
FROM
    orders AS o
        LEFT JOIN
    customers AS c ON o.Customer_Id = c.Customer_Id
WHERE
    Order_Status = 'Completed'
GROUP BY c.State
ORDER BY Completed_Orders DESC;

-- Q15. Find customers who have never placed an order.

SELECT 
    c.Customer_Id,
    CONCAT(c.First_Name, ' ', c.Last_Name) AS Full_Name,
    c.Email
FROM
    customers AS c
        LEFT JOIN
    orders AS o ON c.Customer_Id = o.Customer_Id
WHERE
    o.Customer_Id IS NULL;
    
-- Q16. Find products that have never been ordered.

SELECT 
    p.product_Id, Product_Name
FROM
    products AS p
        LEFT JOIN
    orders AS o ON p.Product_ID = o.Product_ID
WHERE
    o.product_Id IS NULL;

-- Q17. Find the average salary of employees in each department.

SELECT 
    Department, AVG(Salary)
FROM
    employees
GROUP BY Department;

-- Q18. Find departments where the average salary is greater than ₹70,000.

SELECT 
    Department, AVG(Salary) as Average_Salary
FROM
    employees
GROUP BY 
	Department
having Average_salary > 70000;


-- Q19. Find the total payment amount for each payment method.

SELECT 
    payment_method, sum(Amount)
FROM
    payments
WHERE
    payment_status = 'Successful'
GROUP BY payment_method;

-- Q20. Find all orders where the payment status is Failed.

SELECT 
    p.order_ID,
	o.customer_ID,
	p.Amount as Order_Amount,
	p.payment_method,
	p.payment_status
FROM
    payments as p
left join orders as o
	on p.order_Id = o.order_Id
WHERE
    payment_status = 'Failed'
